# All timestamps handled in this module are UTC.

WINDOW_START_HOUR = 2
WINDOW_END_HOUR = 4


def in_maintenance_window(ts):
    return WINDOW_START_HOUR <= ts.hour < WINDOW_END_HOUR


def overdue(ts, now, hours=24):
    return (now - ts).total_seconds() > hours * 3600


def stamp_line(ts, text):
